"""回退后的默认审核页；失败试验保留为有明确边界的诊断。"""
import argparse,json,pathlib,html,re,subprocess
def load(p):return json.loads(p.read_text(encoding='utf8'))
def videos(items,duration):
 figures=''.join(f'<figure><figcaption>{html.escape(label)}</figcaption><video class="sync" controls muted playsinline preload="metadata" src="{src}"></video></figure>' for label,src in items)
 return f'<div class="player" data-duration="{duration}"><div class="controls"><button class="play">同步播放 / 暂停</button><button class="reset">归零</button><label>速度 <select><option value="1">1×</option><option value=".5">0.5×</option><option value=".25">0.25×</option></select></label><input type="range" min="0" max="{duration-.1}" step=".1" value="0"><output>0.0 / {duration:.1f}s</output></div><div class="triple">{figures}</div></div>'
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();out=a.output
 obs=load(out/'observations.json');summary=load(out/'summary.json');guard={s['scene']:s for s in load(out/'guard_summary.json')['scenes']};ev={s['scene']:s for s in load(out/'evidence_summary.json')['scenes']};masks={s['scene']:s for s in load(out/'mask_summary.json')};plan={s['scene']:s for s in load(out/'comparison_plan.json')['scenes']};parts=[]
 for n,actor,duration,note in [('scene_0230','22',5.,'棕色跨界车。旧版侧面去车较好，但CAM5仍可能生成车形；回退不等于这个问题已解决。'),('scene_0255','25',10.,'围栏后的浅色SUV。旧版后半段补景仍模糊/变形，原位GLB还有Ω深度导致的错误裁切；同GLB无遮挡对照保留在旧页。')]:
  base=f'../v77-delete-full/{n}'
  parts.append(f'<section id="active-{n}"><div class="eyebrow">当前默认 · 复用既有完整工程，未重新推理</div><h2>{n} / actor{actor}</h2><p>{note}</p>'+videos([('原视频 · 黄标目标',base+'/original.mp4'),('原位 factual · 原GLB',base+'/factual.mp4'),('DELETE · 回退后的既有结果',base+'/delete.mp4')],duration)+f'<p><a href="../v77-delete-full/index.html#{n}">完整六相机、原生补景和遮挡诊断</a></p></section>')
 parts.append('<section id="failures"><div class="eyebrow">V77-F02 · 本轮退化记录</div><h2>为什么回退：三个案例都没有得到可信无车背景</h2><p>精确mask限制了邻车被改写的范围，但把细轮廓直接输入现成DriveEditor，出现了白车或灰白车形。新增的真实证据太少，未能修复这些反例。以下结果是失败证据，不作为默认世界资产。</p></section>')
 for row in summary['scenes']:
  n=row['scene'];g=guard[n];e=ev[n];m=masks[n];o=obs[n];count=row['comparison_count'];duration=count/10;f0,f1=row['source_frames'];notes=''.join('<li>'+html.escape(t)+'</li>' for t in o['observations'])
  ab=videos([('原视频 · 同时刻',f'{n}/original.mp4'),('A · 精确mask直接补景',f'{n}/precise.mp4'),('B · 真实证据 + residual补景',f'{n}/evidence_first.mp4')],duration)
  prior=videos([('原视频',f'{n}/original.mp4'),('旧版 · 同相机直接DriveEditor补景',f'{n}/legacy.mp4'),('本轮B · 失败，已停用',f'{n}/evidence_first.mp4')],duration) if n!='official_000' else ''
  detail=f'<details><summary>隔离真实证据带来的变化：A/B严格同窗口对照</summary>{ab}</details>' if prior else ab
  extra=f'<details><summary>第三例已经生成的完整3秒A，失败结果全部保留</summary><div class="pair"><video controls muted preload="none" src="{n}/original_full_window.mp4"></video><video controls muted preload="none" src="{n}/precise_full_window.mp4"></video></div><p>B只完成前1秒便按用户要求停止，未填充余帧；这里A是原定完整30帧。</p></details>' if count<30 else ''
  reduced=f'新删除范围减少 {1-m["new_pixels"]/m["old_pixels"]:.1%}' if m['old_pixels'] else '该目标没有旧DriveEditor基线'
  parts.append(f'''<section id="{n}"><div class="eyebrow">失败诊断 · {n} / actor{row['actor']} / CAM{row['camera']} / 原f{f0}–{f1}</div><h2>{n}：{html.escape(o['admission'])}</h2><ul>{notes}</ul><div class="metrics"><span>{reduced}</span><span>90帧输入准备中，该scene真实证据覆盖 <b>{e['evidence_pixels']/e['mask_pixels']:.2%}</b></span><span>车辆guard A/B命中 <b>{len(g['arms']['precise']['blocked_frames'])}/{len(g['arms']['evidence_first']['blocked_frames'])}</b>（各{g['frames']}帧）</span><span>原视频目标检测 <b>{g['source_target_detected_frames']}/{g['frames']}</b></span></div>{prior}{detail}{extra}<p class="note">旧版初始条件历史与本轮不同，旧/新不能当作严格单变量因果对照。mask范围更准不代表删除成功。guard未命中也不能放行：灰白残影可能根本不像检测器认识的车辆。</p>
 <details><summary>目标局部放大、mask和真实证据来源</summary><video class="wide" controls muted preload="none" src="{n}/zoom.mp4"></video><p>放大三栏：原视频 / A / B。固定裁剪，没有超分辨率增强。</p><div class="pair"><figure><figcaption>绿色：实际删除mask</figcaption><video controls muted preload="none" src="{n}/mask.mp4"></video></figure><figure><figcaption>亮绿：已观测证据；紫色：需要生成的洞</figcaption><video controls muted preload="none" src="{n}/evidence_map.mp4"></video></figure></div><img loading="lazy" src="{n}/mask_comparison.jpg"><p>左原图，中旧矩形（第三例为原SAM），右新精确实例mask。</p><img loading="lazy" src="{n}/evidence_provenance.jpg"><p>证据来源只用真实RGB；右上仅填证据，其余保留原目标以显示缺口，不是最终DELETE。图取准备的30帧中证据最多的时刻，第三例可能位于已中止的B推理窗口外。</p></details>
 <details><summary>原生模型输出和guard：失败发生在哪一层</summary><div class="pair"><figure><figcaption>A 原生模型输出</figcaption><video controls muted preload="none" src="{n}/native_precise.mp4"></video></figure><figure><figcaption>B 原生模型输出</figcaption><video controls muted preload="none" src="{n}/native_evidence_first.mp4"></video></figure><figure><figcaption>A 检查，红框为拦截候选</figcaption><video controls muted preload="none" src="{n}/guard_precise.mp4"></video></figure><figure><figcaption>B 检查，红框为拦截候选</figcaption><video controls muted preload="none" src="{n}/guard_evidence_first.mp4"></video></figure></div><p>原图非目标车辆实例匹配用于排除邻车；检测器仍会漏检残影，也可能误检。人工verdict留空，助手已因可见反例阻断三例。</p><a href="{n}/guard_summary.json">guard摘要</a> · <a href="{n}/evidence_stats.json">逐帧证据</a></details><details><summary>固定10时刻静帧</summary><img loading="lazy" src="{n}/contact.jpg"></details></section>''')
 css='''*{box-sizing:border-box}body{background:#0c131c;color:#dce7ef;margin:0;font:16px/1.7 "Microsoft YaHei",system-ui,sans-serif}main{max-width:1600px;padding:34px;margin:auto}h1{font-size:34px;line-height:1.35}h2{font-size:23px}.eyebrow{color:#90b4cd;font-size:13px;letter-spacing:.06em}.banner{background:#153326;border-left:4px solid #5fc998;padding:18px;border-radius:8px}.note{color:#b4c2cf;font-size:14px}a{color:#94ceff}nav{display:flex;gap:24px;flex-wrap:wrap;margin:22px 0}section{margin-top:42px;padding-top:22px;border-top:1px solid #354354}.triple{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}figcaption{background:#203245;padding:9px}video,img{display:block;width:100%;background:#000}video.wide{max-width:1440px}details{border:1px solid #36495b;border-radius:8px;padding:15px;margin-top:16px}summary{cursor:pointer;font-weight:600;margin-bottom:12px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}button,select{border:1px solid #5c7b96;color:#f2f7fc;background:#213d55;border-radius:6px;padding:8px 12px;font:inherit}input[type=range]{flex:1;min-width:140px}.metrics{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.metrics span{padding:8px 12px;background:#192c3d;border-radius:8px}.arch{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}.arch b{background:#14384c;border:1px solid #467588;padding:12px 18px;border-radius:9px}p{max-width:1320px}@media(max-width:1000px){main{padding:18px}.triple,.pair{grid-template-columns:1fr}h1{font-size:27px}}'''
 js='''document.querySelectorAll('.player').forEach(p=>{const vs=[...p.querySelectorAll('video.sync')],seek=p.querySelector('input'),o=p.querySelector('output'),dur=Number(p.dataset.duration);const sync=t=>vs.forEach(v=>{if(Number.isFinite(v.duration))v.currentTime=Math.min(t,v.duration-.001)});p.querySelector('.play').onclick=()=>{if(vs.some(v=>!v.paused))vs.forEach(v=>v.pause());else{if(vs[0].currentTime>dur-.15)sync(0);vs.forEach(v=>v.play().catch(()=>{}))}};p.querySelector('.reset').onclick=()=>{vs.forEach(v=>v.pause());sync(0);seek.value=0};p.querySelector('select').onchange=e=>vs.forEach(v=>v.playbackRate=Number(e.target.value));seek.oninput=()=>sync(Number(seek.value));vs[0].ontimeupdate=()=>{const t=vs[0].currentTime;seek.value=t;o.textContent=t.toFixed(1)+' / '+dur.toFixed(1)+'s';vs.slice(1).forEach(v=>{if(!v.paused&&Math.abs(v.currentTime-t)>.12)v.currentTime=t})};vs[0].onended=()=>vs.forEach(v=>v.pause())});'''
 page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v77 DELETE · 已回退，三案例失败报告</title><style>{css}</style><main><div class="eyebrow">V77 · ROLLBACK REPORT · 2026-09-27</div><h1>已回退上一轮 DriveEditor 方案<br>本轮三案例失败证据完整保留</h1><div class="banner"><b>当前默认：WS-V77-DELETE-FULL-20260927/r1。</b> 已关闭细轮廓直接补景实验入口，恢复旧mask配置与原有Ω/GLB结果。这里的“回退”是恢复已有可复核方案，<b>不是宣称旧版高保真通过</b>。</div><p>本轮按要求尝试精确实例mask、真实证据优先和车辆guard。结果出现白色车辆/灰白车形，效果退化。收到“差就回退”的指示后停止：完成17个DriveEditor窗口，第三例B只生成前10帧，其余不补跑。无新训练、无新Ω重建、未改原GLB。</p><div class="arch"><b>当前：原RGB + 旧mask</b>→<b>DriveEditor补景</b>→<b>冻结Ω背景 + 原GLB</b>→<b>factual / DELETE</b></div><p class="note">试验分支：SAM2精确mask → Ω深度/GT相机warp原RGB → 证据+residual补景 → 车辆/视觉检查 → <b>发现退化，阻断并回退</b>。精确mask与证据代码保留为实验，不作为默认入口。</p><nav><a href="#active-scene_0230">回退后0230</a><a href="#active-scene_0255">回退后0255</a><a href="#failures">三案例失败对照</a><a href="report.md">详细报告</a><a href="rollback.json">当前配置</a></nav>{''.join(parts)}<section><h2>验证与边界</h2><p>{summary['total_videos']}段本轮诊断视频、{summary['total_decoded_frames']}帧已实际解码；默认三栏复用上一轮已验证视频。90帧证据准备与已生成图的mask外不变/来源检查通过，8项语义与准入测试通过。这些不代表补景质量通过。人工verdict仍留空。</p><p><a href="validation.json">像素验证</a> · <a href="background_admission.json">失败背景未准入</a> · <a href="rollback_validation.json">旧实现未改验证</a> · <a href="observations.json">观察记录</a> · <a href="comparison_plan.json">实际完成帧数</a></p></section></main><script>{js}</script></html>'''
 (out/'index.html').write_text(page,encoding='utf8');(out/'review.js').write_text(js,encoding='utf8')
 refs=re.findall(r'(?:src|href)="([^"]+)"',page);missing=[]
 for ref in refs:
  if ref.startswith(('#','https:','http:')):continue
  if not (out/ref.split('#')[0]).exists():missing.append(ref)
 subprocess.run(['node','--check',str(out/'review.js')],check=True)
 if missing:raise ValueError(missing)
 (out/'page_validation.json').write_text(json.dumps({'local_references_checked':len(refs),'missing':missing,'javascript_syntax':'passed','browser_interaction':'not_exercised','human_verdict':None},ensure_ascii=False,indent=2),encoding='utf8')
if __name__=='__main__':main()
